import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o as a,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Cursor CLI","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/cursor/cursor-cli.md","filePath":"products/ai-coding/cursor/cursor-cli.md","lastUpdated":1787048027000}'),o={name:"products/ai-coding/cursor/cursor-cli.md"};function r(n,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="cursor-cli" tabindex="-1">Cursor CLI <a class="header-anchor" href="#cursor-cli" aria-label="Permalink to &quot;Cursor CLI&quot;">​</a></h1><p>Cursor CLI is the <strong>same coding agent</strong> in a terminal: interactive session, or print mode for scripts and CI. The binary is <strong><code>agent</code></strong>, not <code>cursor</code>, and not the Origin CLI <code>origin</code>.</p><blockquote><p>Official: <a href="https://cursor.com/docs/cli/overview" target="_blank" rel="noreferrer">CLI overview</a>, <a href="https://cursor.com/docs/cli/installation" target="_blank" rel="noreferrer">Installation</a>, <a href="https://cursor.com/docs/cli/using" target="_blank" rel="noreferrer">Using</a>, <a href="https://cursor.com/docs/cli/headless" target="_blank" rel="noreferrer">Headless</a>.</p><p>Recipes for CI copy-paste stay in the <a href="./cursor-cookbook.html#use-cursor-cli-in-the-terminal-or-ci">cookbook</a>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A shell on macOS, Linux, WSL, or Windows PowerShell</li><li>A git checkout you are willing to edit</li><li>For scripts / CI: a <code>CURSOR_API_KEY</code> from the dashboard</li></ul><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>After this page you can:</p><ol><li>Install <code>agent</code> and run one interactive turn</li><li>Switch Agent / Plan / Ask the same way the editor does</li><li>Use <code>-p</code> for headless, and <code>--force</code> when you actually want writes</li><li>Hand a session to Cloud with <code>&amp;</code>, without confusing <code>agent</code> and <code>origin</code></li></ol><hr><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS, Linux, WSL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://cursor.com/install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows PowerShell</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">irm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://cursor.com/install?win32=true&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> iex</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>If the shell cannot find <code>agent</code>, add <code>~/.local/bin</code> to <code>PATH</code> (bash: <code>~/.bashrc</code>; zsh: <code>~/.zshrc</code>). Update: <code>agent update</code> (auto-update is on by default).</p><h2 id="interactive-mode" tabindex="-1">Interactive mode <a class="header-anchor" href="#interactive-mode" aria-label="Permalink to &quot;Interactive mode&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;refactor the auth module to use JWT tokens&quot;</span></span></code></pre></div><p>The agent can write, review, and modify code. Approve commands as they come.</p><h3 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h3><p>Same modes as the editor. Switch with slash commands, <code>Shift+Tab</code>, or <code>--mode</code>.</p><table tabindex="0"><thead><tr><th>Mode</th><th>What it does</th><th>How</th></tr></thead><tbody><tr><td><strong>Agent</strong></td><td>Full tools for coding tasks</td><td>Default</td></tr><tr><td><strong>Plan</strong></td><td>Design first; clarifying questions</td><td><code>Shift+Tab</code>, <code>/plan</code>, <code>--plan</code>, <code>--mode=plan</code></td></tr><tr><td><strong>Ask</strong></td><td>Read-only exploration</td><td><code>/ask</code>, <code>--mode=ask</code></td></tr></tbody></table><p>Debug Mode is an <strong>editor</strong> constraint. Do not invent a CLI <code>--mode=debug</code>.</p><h3 id="session-extras-official" tabindex="-1">Session extras (official) <a class="header-anchor" href="#session-extras-official" aria-label="Permalink to &quot;Session extras (official)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>How</th></tr></thead><tbody><tr><td>Cloud handoff</td><td>Prefix a message with <code>&amp;</code></td></tr><tr><td>Previous chats</td><td><code>agent ls</code></td></tr><tr><td>Latest conversation</td><td><code>agent resume</code> or <code>agent --continue</code></td></tr><tr><td>Specific id</td><td><code>agent --resume=&quot;chat-id-here&quot;</code></td></tr><tr><td>Review diff</td><td><code>Ctrl+R</code> (then <code>i</code> for follow-up)</td></tr><tr><td>Newline</td><td><code>Shift+Enter</code> (or <code>Ctrl+J</code> in tmux)</td></tr><tr><td>Exit</td><td><code>Ctrl+D</code> twice</td></tr><tr><td><code>@</code> files / folders</td><td>Same idea as the editor</td></tr><tr><td>Shrink context</td><td><code>/summarize</code> (<code>/compress</code> is an alias)</td></tr><tr><td>Worktree</td><td><code>agent --worktree &quot;…&quot;</code> (optional name; lives under <code>~/.cursor/worktrees/</code>)</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Mid-conversation → Cloud Agent</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">refactor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> comprehensive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span></code></pre></div><p>Pick that run up at <a href="https://cursor.com/agents" target="_blank" rel="noreferrer">cursor.com/agents</a> or on mobile.</p><p>Sandbox: <code>/sandbox</code> or <code>--sandbox &lt;mode&gt;</code> (<code>enabled</code> / <code>disabled</code>). Settings persist. Sudo: the CLI shows a masked password prompt; the <strong>model never sees</strong> the password.</p><h2 id="non-interactive-ci" tabindex="-1">Non-interactive / CI <a class="header-anchor" href="#non-interactive-ci" aria-label="Permalink to &quot;Non-interactive / CI&quot;">​</a></h2><p>Use <strong>print mode</strong> (<code>-p</code> / <code>--print</code>) for scripts and CI.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CURSOR_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">your_api_key_here</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;find and fix performance issues&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;gpt-5&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;review these changes for security issues&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text</span></span></code></pre></div><h3 id="does-p-write-files" tabindex="-1">Does <code>-p</code> write files? <a class="header-anchor" href="#does-p-write-files" aria-label="Permalink to &quot;Does \`-p\` write files?&quot;">​</a></h3><p>Treat the dedicated <a href="https://cursor.com/docs/cli/headless" target="_blank" rel="noreferrer">Headless</a> page as the script contract:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Propose only — will not modify files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Add JSDoc comments to this file&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Apply edits without confirmation</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Refactor this code to use modern ES6+ syntax&quot;</span></span></code></pre></div><p><code>--force</code> is the write switch. HTML headless also documents the alias <strong><code>--yolo</code></strong>. The <code>.md</code> snapshot of that page names <code>--force</code> only.</p><p><code>cli/using.md</code> still says “Cursor has full write access in non-interactive mode.” Prefer Headless for CI, and <strong>pass <code>--force</code> when you want disk changes</strong>.</p><p>Authenticate scripts with <code>CURSOR_API_KEY</code>. Output: <code>--output-format text</code> (default for <code>-p</code>), <code>json</code>, or <code>stream-json</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;Review recent changes and write feedback to review.txt&quot;</span></span></code></pre></div><h2 id="rules-mcp-acp" tabindex="-1">Rules, MCP, ACP <a class="header-anchor" href="#rules-mcp-acp" aria-label="Permalink to &quot;Rules, MCP, ACP&quot;">​</a></h2><p>The CLI loads the same <a href="https://cursor.com/docs/rules" target="_blank" rel="noreferrer">rules</a> as the editor from <code>.cursor/rules</code>. It also reads root <strong><code>AGENTS.md</code></strong> and <strong><code>CLAUDE.md</code></strong>.</p><p>MCP comes from the project&#39;s <strong><code>mcp.json</code></strong> (the same servers as the editor). Cloud Agents use the <strong>team</strong> MCP list on cursor.com/agents — different source.</p><p>ACP: <code>agent acp</code> runs Cursor CLI as an ACP server over <code>stdio</code> (JSON-RPC). JetBrains talks ACP too — <a href="https://cursor.com/docs/integrations/jetbrains" target="_blank" rel="noreferrer">JetBrains</a>.</p><h2 id="agent-vs-origin" tabindex="-1"><code>agent</code> vs <code>origin</code> <a class="header-anchor" href="#agent-vs-origin" aria-label="Permalink to &quot;\`agent\` vs \`origin\`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Binary</th><th>Product</th><th>Tutorial</th></tr></thead><tbody><tr><td><strong><code>agent</code></strong></td><td>Coding agent (this page)</td><td>you are here</td></tr><tr><td><strong><code>origin</code></strong></td><td>Git forge CLI</td><td><a href="./origin.html">Origin</a></td></tr></tbody></table><p>Do not run <code>curl https://cursor.com/install</code> and expect a git host. That install is <strong><code>agent</code></strong>.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><ul><li>You are already in tmux / SSH / a CI job</li><li>You want the same Rules / <code>AGENTS.md</code> without opening the GUI</li><li>You need a worktree (<code>--worktree</code>) so the agent does not edit your current checkout</li></ul><p>Stay in the editor for Tab, Inline Edit, and Debug Mode. Use <a href="./cloud-agents.html">Cloud Agents</a> when the laptop should sleep. Use <a href="./cursor-sdk.html">SDK</a> when the caller is <strong>your</strong> TypeScript / Python process.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Do this</th></tr></thead><tbody><tr><td>Type <code>cursor</code> in the terminal</td><td>Binary is <strong><code>agent</code></strong></td></tr><tr><td><code>agent -p</code> in CI, no file changes</td><td>Add <strong><code>--force</code></strong> (Headless page)</td></tr><tr><td>Trust <code>using.md</code> “full write access” alone</td><td>Follow <strong>Headless</strong> + <code>--force</code></td></tr><tr><td>Expect Debug Mode</td><td>Editor only</td></tr><tr><td>Confuse with Origin CLI</td><td><code>origin</code> is the forge</td></tr><tr><td>Prefix Cloud handoff without <code>&amp;</code></td><td><code>&amp; refactor …</code></td></tr><tr><td>Assume Cloud team MCP</td><td>CLI reads <strong>project <code>mcp.json</code></strong></td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./cursor-cookbook.html#use-cursor-cli-in-the-terminal-or-ci">Cookbook · CLI</a> — CI snippets</li><li><a href="./cloud-agents.html">Cloud Agents</a> — <code>&amp;</code> landing zone</li><li><a href="./cursor-sdk.html">Cursor SDK</a> — same agent, in-process</li><li>Official: <a href="https://cursor.com/docs/cli/overview" target="_blank" rel="noreferrer">Overview</a>, <a href="https://cursor.com/docs/cli/installation" target="_blank" rel="noreferrer">Installation</a>, <a href="https://cursor.com/docs/cli/using" target="_blank" rel="noreferrer">Using</a>, <a href="https://cursor.com/docs/cli/headless" target="_blank" rel="noreferrer">Headless</a></li></ul>`,48)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
